#include <iostream>
using namespace std;

int main() {
    const int N = 5;
    int marks[N];
    string subject[N] = {"Hindi", "English", "Maths", "Science", "Computer"};

    for (int i = 0; i < N; i++) {
        cout << "Marks in " << subject[i] << ": ";
        cin >> marks[i];
    }

    int total = 0;
    for (int i = 0; i < N; i++)
