#include <iostream>
using namespace std;

int main() {
    string day[7] = {"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"};
    double temp[7] = {38.5, 40.2, 41.0, 39.8, 42.3, 37.6, 36.9};

    int maxPos = 0, minPos = 0;
    for (int i = 1; i < 7; i++) {
        if (temp[i] > temp[maxPos]) maxPos = i;
        if (temp[i] < temp[minPos]) minPos = i;
    }
    cout << "Hottest day : " << day[maxPos] << " (" << temp[maxPos] << " C)"
<< endl;
    cout << "Coolest day : " << day[minPos] << " (" << temp[minPos] << " C)"
<< endl;
    return 0;
}

