#include <iostream>
using namespace std;

int main() {
    int a[6] = {64, 25, 90, 12, 45, 78};
    int n = 6;

    for (int pass = 1; pass < n; pass++) {
        for (int j = 0; j < n - pass; j++) {
            if (a[j] > a[j + 1]) {        // wrong order: swap
                int t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
            }
        }
        cout << "After pass " << pass << ": ";
        for (int k = 0; k < n; k++) cout << a[k] << " ";
        cout << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

double average(int arr[], int n) {
    int sum = 0;
    for (int i = 0; i < n; i++)
        sum += arr[i];
    return (double)sum / n;
}

int countAbove(int arr[], int n, double limit) {
    int c = 0;
    for (int i = 0; i < n; i++)
        if (arr[i] > limit) c++;
    return c;
}

int main() {
    int runs[10] = {45, 12, 78, 0, 33, 101, 56, 8, 67, 24};
    double avg = average(runs, 10);
    cout << "Average runs per match : " << avg << endl;
    cout << "Matches above average  : " << countAbove(runs, 10, avg) << endl;
    return 0;
}

#include <iostream>
