        {78, 85, 90, 88},
        {66, 72, 81, 58},
        {88, 91, 79, 94}
    };

    cout << left << setw(8) << "Name" << right
         << setw(6) << "Sub1" << setw(6) << "Sub2"
         << setw(6) << "Sub3" << setw(6) << "Sub4" << setw(8) << "Total" <<
endl;

    for (int i = 0; i < 3; i++) {
        int total = 0;
        cout << left << setw(8) << name[i] << right;
        for (int j = 0; j < 4; j++) {
