        int colSum = 0;
        for (int i = 0; i < 3; i++)
            colSum += marks[i][j];
        cout << setw(6) << colSum / 3.0;
    }
    cout << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string first = "Patna";
    string second = "Bihar";
    string place = first + ", " + second;            // joining

    cout << "Place          : " << place << endl;
    cout << "Length         : " << place.length() << endl;
    cout << "First letter   : " << place[0] << endl;
    cout << "substr(0, 5)   : " << place.substr(0, 5) << endl;
    cout << "find(\"Bihar\")  : " << place.find("Bihar") << endl;
    if (first < second)
        cout << first << " comes before " << second << " in dictionary order"
<< endl;
    else
        cout << second << " comes before " << first << " in dictionary order"
<< endl;

    place.replace(0, 5, "Gaya");
    cout << "After replace  : " << place << endl;
    return 0;
}

#include <iostream>
#include <string>
#include <cctype>
using namespace std;

int main() {
    string line;
    cout << "Enter a sentence: ";
    getline(cin, line);

    int vowels = 0, consonants = 0, digits = 0, spaces = 0;
    for (int i = 0; i < (int)line.length(); i++) {
        char ch = tolower(line[i]);
        if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u')
            vowels++;
        else if (isalpha(ch))
            consonants++;
        else if (isdigit(ch))
            digits++;
        else if (ch == ' ')
            spaces++;
    }
    cout << "Vowels     : " << vowels << endl;
    cout << "Consonants : " << consonants << endl;
    cout << "Digits     : " << digits << endl;
    cout << "Spaces     : " << spaces << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

string reverseOf(string s) {
    string r = "";
    for (int i = (int)s.length() - 1; i >= 0; i--)
        r += s[i];
    return r;
}

int main() {
    string word;
    cout << "Enter a word: ";
    cin >> word;
    string rev = reverseOf(word);
    cout << "Reverse: " << rev << endl;
    if (rev == word)
        cout << word << " is a palindrome." << endl;
    else
        cout << word << " is not a palindrome." << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    const int C = 4;
    string candidate[C] = {"Riya", "Aman", "Sana", "Vikas"};
    int votes[C] = {0, 0, 0, 0};       // counters start at zero

    cout << "Candidates: 1-Riya 2-Aman 3-Sana 4-Vikas" << endl;
    cout << "Enter votes one by one (0 to stop):" << endl;

    int v, invalid = 0;
    cin >> v;
    while (v != 0) {
        if (v >= 1 && v <= C)
            votes[v - 1]++;               // vote 1 goes to index 0
        else
            invalid++;
        cin >> v;
    }

    int winner = 0;
    for (int i = 0; i < C; i++) {
        cout << candidate[i] << " : " << votes[i] << endl;
        if (votes[i] > votes[winner])
            winner = i;
    }
    cout << "Invalid votes: " << invalid << endl;
    cout << "Winner: " << candidate[winner] << endl;
    return 0;
}
